using AiBox.DevPortal.Models;

namespace AiBox.DevPortal.Services
{
    public sealed class ContextSuggestionService
    {
        public IReadOnlyList<string> SuggestFiles(string userRequest, ProjectKnowledgeIndex knowledgeIndex)
        {
            if (string.IsNullOrEmpty(userRequest) || knowledgeIndex == null)
            {
                return [];
            }

            var tokenSet = new HashSet<string>(userRequest.Split(' '));
            var suggestions = new List<string>();

            foreach (var item in knowledgeIndex.Items)
            {
                var score = 0;
                score += tokenSet.Count(token => item.RelativePath.Contains(token)) * 5;
                score += tokenSet.Count(token => item.FileType.Contains(token)) * 3;
                score += tokenSet.Count(token => item.Name.Contains(token)) * 3;
                score += tokenSet.Count(token => item.Namespace.Contains(token)) * 2;
                score += tokenSet.Count(token => item.Kind.Contains(token)) * 2;
                score += tokenSet.Count(token => item.Summary.Contains(token)) * 1;
                score += tokenSet.Count(token => item.Classes.Contains(token)) * 4;
                score += tokenSet.Count(token => item.Interfaces.Contains(token)) * 4;
                score += tokenSet.Count(token => item.Records.Contains(token)) * 4;

                if (score > 0)
                {
                    suggestions.Add(item.RelativePath);
                }
            }

            return suggestions.OrderByDescending(path => score).Take(10).ToList();
        }
    }
}
